export const GARY_TOOL_CATALOG = {"sourceCommit":"f3e3f54b6c93916388a0a3dc6a439893a9abe37a","tools":[{"name":"gary_add_company_scope","upstreamName":"add_company_scope","description":"Add the domain name/IP/CIDR/ICP registration/enterprise keywords to a company's [Asset Scope] - the domain name, network and ICP will automatically claim the hit assets, and the keywords are only provided to the Agent as a scope prompt.The company name is unique: If company does not exist, create a new one, and if it already exists, reuse it (only merge the scope).Scope is one line at a time, and the system automatically identifies: root domain name / URL / single IP / CIDR network segment / ICP registration / enterprise keywords.Be sure to provide reason with the attribution basis (whois/certificate/ASN, etc.).Guardrails: Reject naked TLDs and overly wide network segments (IPv4 prefixes must be /16-/32, IPv6 prefixes must be /32-/128), illegal lines will be skipped and returned in errors.","inputSchema":{"properties":{"company":{"description":"Company name (create if it does not exist, reuse if it exists; the name is unique)","type":"string"},"logo":{"description":"Company icon URL (optional; only valid when creating a new company)","type":"string"},"reason":{"description":"Basis of attribution (evidence/source), must be filled in","type":"string"},"scope":{"description":"Asset scope, one line per line: domain name / URL / IP / CIDR / ICP filing / enterprise keywords","type":"string"}},"required":["company","scope"],"type":"object"},"readOnly":false,"category":"gary-security"},{"name":"gary_add_hint","upstreamName":"add_hint","description":"Hook the human/master agent's strategic prompts to the exploration graph and the planner will read it the next time it generates an intent.★Priority batch: Put multiple hints into the hints array and submit them at once (saving round trips than calling them one by one). Returns an array of ids, in the same length and order as hints (failure item id=0, see errors for details). For a single item, hints are omitted and given directly to the top-level text.","inputSchema":{"properties":{"asset_ids":{"description":"Anchored asset IDs (optional, zero, one or several)","items":{"type":"integer"},"type":"array"},"hints":{"description":"[Use this first] The prompt array to be added will be processed in order. Each element field is the same as the top-level field below (text/asset_ids/traffic_refs). The returned ids are of the same length and order as this array.","items":{"properties":{"asset_ids":{"items":{"type":"integer"},"type":"array"},"text":{"description":"Prompt content","type":"string"},"traffic_refs":{"description":"Optional: The traffic references that have been verified and correspond to the specific vulnerabilities in this tip are kept in order; after handover, report_finding can pass evidence_hint_id to carry these references.","items":{"properties":{"note":{"description":"What conclusion does this flow support?","type":"string"},"role":{"description":"baseline / proof / verification / supporting","type":"string"},"traffic_id":{"description":"Real traffic ID","type":"string"}},"required":["traffic_id"],"type":"object"},"type":"array"}},"type":"object"},"type":"array"},"text":{"description":"[Single item] Prompt content, such as 'Focus on mining post-authentication interfaces'","type":"string"},"traffic_refs":{"description":"Optional: The traffic references that have been verified and correspond to the specific vulnerabilities in this tip are kept in order; after handover, report_finding can pass evidence_hint_id to carry these references.","items":{"properties":{"note":{"description":"What conclusion does this flow support?","type":"string"},"role":{"description":"baseline / proof / verification / supporting","type":"string"},"traffic_id":{"description":"Real traffic ID","type":"string"}},"required":["traffic_id"],"type":"object"},"type":"array"}},"type":"object"},"readOnly":false,"category":"gary-security"},{"name":"gary_add_intent","upstreamName":"add_intent","description":"Generate [exploration direction] and write it into frontier, and connect it to the exploration link. The intention is an open direction of exploration, not a fixed type - use a summary sentence to freely describe what is to be explored/verified/exploited.★Priority batch: Multiple new directions filtered out in one round are put into the intents array and submitted at once (saving round trips than calling one by one). Returns an array of ids, in the same length and order as intents (failure item id=0, see errors for details). For a single item, the intents are omitted and given directly to the top-level summary.","inputSchema":{"properties":{"asset_ids":{"description":"[Target asset ID] to be tested/attacked in this direction (**try to pass**, 0/1/multiple; it is the asset ID returned by list_assets, not the exploration node ID): which assets (site/interface/parameter/host, etc.) this exploration direction targets. As long as the direction revolves around certain specific assets, it must be uploaded - it is a structured markup of \"what goals are this exploration targeting?\" and is used to cover duplication and connect intentions to asset links. Only leave this blank if you are doing pure global reconnaissance and really don't have a specific target asset.","items":{"type":"integer"},"type":"array"},"intents":{"description":"[Use this first] The array of exploration directions to be added is processed in order. Each element field is the same as the top-level field below (summary/asset_ids/parent_ids/priority). The returned ids are of the same length and order as this array.","items":{"type":"object"},"type":"array"},"parent_ids":{"description":"Upstream anchor id (optional, 0/1/multiple): This direction is derived from the [confirmed facts/findings]. **Only existing fact/finding node ids can be filled in, not intentions/goals/prompts** - Intentions must be anchored on confirmed knowledge, driven by discovery rather than planning out of thin air. If multiple facts jointly generate a new intention, please pass multiple; please leave the top-level new reconnaissance direction blank (it will automatically be linked to the origin fact of the task).","items":{"type":"integer"},"type":"array"},"priority":{"description":"Priority 0-10, default 5","type":"integer"},"summary":{"description":"[Single article] Describe this exploration direction in one sentence: what to do + why. Just write the direction clearly and it does not depend on the asset ID.","type":"string"}},"type":"object"},"readOnly":false,"category":"gary-security"},{"name":"gary_add_task_hint","upstreamName":"add_task_hint","description":"Inject strategic hints into the specified task (the planner of the task will read it when generating intent in the next round).★Batch priority: Put multiple hints into the hints array and submit them at once (return the ids array, in the same length and order as hints, and the failed item id=0); for a single hint, omit hints and send it directly to the top-level text.","inputSchema":{"properties":{"asset_ids":{"description":"Anchored asset IDs (optional, zero, one or several IDs belonging to this task)","items":{"type":"integer"},"type":"array"},"hints":{"description":"[Use this first] Prompt array, each element field is the same as the top level (text/asset_ids/traffic_refs).","items":{"properties":{"asset_ids":{"items":{"type":"integer"},"type":"array"},"text":{"description":"Prompt content","type":"string"},"traffic_refs":{"description":"Optional: The traffic references that have been verified and correspond to the specific vulnerabilities in this tip are kept in order; after handover, report_finding can pass evidence_hint_id to carry these references.","items":{"properties":{"note":{"description":"What conclusion does this flow support?","type":"string"},"role":{"description":"baseline / proof / verification / supporting","type":"string"},"traffic_id":{"description":"Real traffic ID","type":"string"}},"required":["traffic_id"],"type":"object"},"type":"array"}},"type":"object"},"type":"array"},"task_id":{"description":"task id","type":"string"},"text":{"description":"[Single item] Prompt content","type":"string"},"traffic_refs":{"description":"Optional: The traffic references that have been verified and correspond to the specific vulnerabilities in this tip are kept in order; after handover, report_finding can pass evidence_hint_id to carry these references.","items":{"properties":{"note":{"description":"What conclusion does this flow support?","type":"string"},"role":{"description":"baseline / proof / verification / supporting","type":"string"},"traffic_id":{"description":"Real traffic ID","type":"string"}},"required":["traffic_id"],"type":"object"},"type":"array"}},"required":["task_id"],"type":"object"},"readOnly":false,"category":"gary-security"},{"name":"gary_add_task_scope","upstreamName":"add_task_scope","description":"Add the test scope to [this task] - this is the authorization boundary of this task and also the denominator of asset test coverage.kind supports: company (assets under the entire company's name) / root_domain (the entire root domain, including all subdomains) / subdomain (a single precise subdomain) / ip / cidr / icp / keyword.Description: Hosts encountered by workers one by one will be [automatically] added to the scope (precise subdomain) by the system; this tool is used to [active expansion] - include the entire root domain/entire company, or additionally specify a certain subdomain/IP.value: company passes the company name or id (the company must already exist); root_domain/subdomain passes the domain name; ip/cidr passes the IP or network segment; icp/keyword passes the registration number or company keyword.Be sure to give reason a basis (auditable). Use the entries array for multiple entries.","inputSchema":{"properties":{"entries":{"description":"Batch: [{kind, value}]. kind∈company/root_domain/subdomain/ip/cidr/icp/keyword.","items":{"type":"object"},"type":"array"},"kind":{"description":"[Single entry] company/root_domain/subdomain/ip/cidr/icp/keyword","type":"string"},"reason":{"description":"Basis for joining (for auditing), be sure to fill in","type":"string"},"value":{"description":"[Single entry] Company name or id / domain name / IP / CIDR / ICP / keyword","type":"string"}},"type":"object"},"readOnly":false,"category":"gary-security"},{"name":"gary_bash","upstreamName":"Bash","description":"Executes a shell command in the working directory and returns combined stdout and stderr. Use for running tests, builds, package managers, and git. Prefer the dedicated file tools for file work. Set run_in_background to return immediately and read the output later.\n\nThe command runs through the shell, so you are not limited to one command: chain steps with && or ;, use pipes, and pass multi-line scripts or heredocs. For anything beyond a simple one-liner — loops, parsing, string/JSON handling, HTTP logic, computation — prefer writing a short script (Python, Node, shell, etc.) and executing it (e.g. via a heredoc or by writing a file then running it) rather than forcing everything into a single command. A timeout (default 120s, max 600s) applies. Avoid commands needing interactive input.","inputSchema":{"properties":{"command":{"description":"The shell command to execute.","type":"string"},"run_in_background":{"description":"Run in the background and return immediately; read its output later with TaskOutput or Read, and you are notified when it completes. A foreground command that exceeds its timeout is also moved to the background automatically.","type":"boolean"},"timeout_ms":{"description":"Timeout in ms (default 120000, max 600000).","type":"integer"}},"required":["command"],"type":"object"},"readOnly":false,"category":"gary-security"},{"name":"gary_bind_finding_traffic","upstreamName":"bind_finding_traffic","description":"Patch verified, real HTTP traffic for registered vulnerabilities. finding_id uses an independent vulnerability record ID; do not pass the exploration node ID. All references in the same batch succeed or all fail. Repeated references will not cover existing instructions. Patching will mark existing reports for update; do not re-detect or re-create vulnerabilities for patching.","inputSchema":{"properties":{"finding_id":{"description":"Individual vulnerability record ID, read from the finding_id field of list_task_findings / get_task_node_detail","type":"string"},"traffic_refs":{"description":"Optional: The traffic references that have been verified and correspond to the specific vulnerabilities in this tip are kept in order; after handover, report_finding can pass evidence_hint_id to carry these references.","items":{"properties":{"note":{"description":"What conclusion does this flow support?","type":"string"},"role":{"description":"baseline / proof / verification / supporting","type":"string"},"traffic_id":{"description":"Real traffic ID","type":"string"}},"required":["traffic_id"],"type":"object"},"type":"array"}},"required":["finding_id","traffic_refs"],"type":"object"},"readOnly":false,"category":"gary-security"},{"name":"gary_create_custom_tool","upstreamName":"create_custom_tool","description":"[Important] When installing some tools that are not available on the platform, call this tool to put the installed tools into the platform so that the platform can call it! Create a custom tool (shell/command/script/http). shell=bash environment declaration, only key+description+agents, no exec/schema required.","inputSchema":{"properties":{"agents":{"description":"Binding agent key (optional)","items":{"type":"string"},"type":"array"},"deferred":{"description":"Whether to delay (the shell type is invalid; only uncommon tools of command/script/http are enabled)","type":"boolean"},"description":{"description":"Description sent to the model","type":"string"},"enabled":{"description":"Whether to enable (default true)","type":"boolean"},"exec":{"description":"Execution specifications (not required for shell type): command→{command}; script→{code}; http→{method,url,headers,body,proxy,use_recording_proxy}","type":"object"},"key":{"description":"Tool key (begins with lowercase letter, letter/number/underscore)","type":"string"},"kind":{"description":"shell | command | script (Python only) | http. shell=bash environment statement (only informs the model that the tool can be called directly in bash without exec/schema); the other three require exec","type":"string"},"schema":{"description":"Parameter JSON-Schema (shell/command/script can be left blank; http is required and must contain properties)","type":"object"}},"required":["key","kind"],"type":"object"},"readOnly":false,"category":"gary-security"},{"name":"gary_create_mcp","upstreamName":"create_mcp","description":"Create an MCP server (stdio/http/sse). After creation, its tools need to be authorized according to agent visibility.","inputSchema":{"properties":{"args":{"description":"Command parameter array","items":{"type":"string"},"type":"array"},"command":{"description":"stdio startup command (such as npx)","type":"string"},"enabled":{"description":"Whether to enable (default true)","type":"boolean"},"env":{"description":"Environment variable {KEY:VALUE}","type":"object"},"insecure":{"description":"http: Skip TLS certificate verification (set to true when self-signing the certificate, default to false)","type":"boolean"},"name":{"description":"MCP server name","type":"string"},"transport":{"description":"stdio | http / sse","type":"string"},"url":{"description":"http/sse URL","type":"string"}},"required":["name","transport"],"type":"object"},"readOnly":false,"category":"gary-security"},{"name":"gary_create_skill","upstreamName":"create_skill","description":"Create a new skill (write SKILL.md, agentskills.io specification). name lowercase letters/numbers/hyphens.","inputSchema":{"properties":{"description":{"description":"Skill description (required, describe what it does/when to use it)","type":"string"},"instructions":{"description":"Markdown text description (optional)","type":"string"},"name":{"description":"Skill name (begins with a lowercase letter, letters/numbers/hyphens)","type":"string"}},"required":["name","description"],"type":"object"},"readOnly":false,"category":"gary-security"},{"name":"gary_delete_assets_by_host","upstreamName":"delete_assets_by_host","description":"Deleting assets accurately by host: Delete the domain name/subdomain name of the host, as well as the services and interfaces (endpoints) under it.host matches exactly (lowercase, remove spaces), not fuzzy/wildcarding.Passing the root domain name (such as example.com) will also delete its subdomain name and its services/interfaces; passing the subdomain name (such as a.example.com) or IP will only delete the host itself and its services/interfaces.⚠️ Hard deletion, affects the global asset library (shared across tasks), and cannot be undone.","inputSchema":{"properties":{"host":{"description":"Host to be deleted: domain name/subdomain name/IP. An exact match like example.com or a.example.com or 1.2.3.4","type":"string"}},"required":["host"],"type":"object"},"readOnly":false,"category":"gary-security"},{"name":"gary_edit","upstreamName":"Edit","description":"Performs an exact string replacement in a file. old_string must match exactly once unless replace_all is set. Read the file first so old_string matches precisely.\n\nold_string must match the file exactly (whitespace included) and be unique unless replace_all is true. new_string must differ from old_string.","inputSchema":{"properties":{"file_path":{"description":"Path of the file to edit.","type":"string"},"new_string":{"description":"Replacement text.","type":"string"},"old_string":{"description":"Exact text to replace.","type":"string"},"replace_all":{"description":"Replace all occurrences.","type":"boolean"}},"required":["file_path","old_string","new_string"],"type":"object"},"readOnly":false,"category":"gary-security"},{"name":"gary_expand_digest","upstreamName":"expand_digest","description":"Expand a cold digest: Return a compact list of its collapsed members (id/summary/state/confidence), with the same shape as the overview recent_facts/recent_done_intents. For complete details/evidence of a piece of information use node_detail(member_id).","inputSchema":{"properties":{"id":{"description":"digest node id (from overview cold_digests)","type":"integer"}},"required":["id"],"type":"object"},"readOnly":false,"category":"gary-security"},{"name":"gary_get_finding_retest_context","upstreamName":"get_finding_retest_context","description":"Read the vulnerability evidence snapshot, retest status, supplementary instructions and current task constraints associated with the current retest session. No parameters, only this session can be read.","inputSchema":{"properties":{},"type":"object"},"readOnly":true,"category":"gary-security"},{"name":"gary_get_finding_traffic","upstreamName":"get_finding_traffic","description":"Read the real traffic evidence bound to the vulnerability without relying on the capture switch. finding_id uses the individual vulnerability record ID returned by report_finding JSON (not the discovery node ID of the first row). Do not pass binding_id to get the list and version; an empty list is normal. For non-HTTP vulnerabilities such as TCP or when they are not collected, reports can still be written based on text/command evidence without forcing binding. When there is binding, read the text in sections according to binding_id, side(request/response), and offset. When writing the report, the read version is passed to update_finding_report as evidence_version, and the latter's finding_id still uses the exploration node ID.","inputSchema":{"properties":{"binding_id":{"description":"The binding ID in the list. If omitted, the list will be returned.","type":"string"},"finding_id":{"description":"Individual vulnerability record ID","type":"string"},"length":{"type":"integer"},"offset":{"type":"integer"},"side":{"description":"request or response, default response","type":"string"}},"required":["finding_id"],"type":"object"},"readOnly":true,"category":"gary-security"},{"name":"gary_get_task_graph","upstreamName":"get_task_graph","description":"Read the exploration graph overview of the specified task (same as graph_overview: asset count/frontier/discovery/coverage, etc.), specify the task with task_id.","inputSchema":{"properties":{"task_id":{"description":"task id","type":"string"}},"required":["task_id"],"type":"object"},"readOnly":true,"category":"gary-security"},{"name":"gary_get_task_node_detail","upstreamName":"get_task_node_detail","description":"Read the complete content of an exploration graph node in the specified task (findings/facts/intentions/goals: summary + details/evidence/PoC). id is the id of the exploration node (such as the id returned by report_finding, or the id in list_task_findings). Use it to get complete evidence of the vulnerability before writing a vulnerability report.","inputSchema":{"properties":{"id":{"description":"Exploration graph node id (non-asset id)","type":"integer"},"task_id":{"description":"task id","type":"string"}},"required":["task_id","id"],"type":"object"},"readOnly":true,"category":"gary-security"},{"name":"gary_get_task_worker_trace","upstreamName":"get_task_worker_trace","description":"See the execution process of a certain work (intention) in the specified task: get_task_worker_trace(task_id, intent_id) to see the step summary; then add step_ids=[...] to get the complete content of those steps (up to 5 at a time, only the first 5 will be returned in multi-pass).","inputSchema":{"properties":{"intent_id":{"description":"Intent id (work in this task)","type":"integer"},"step_ids":{"description":"Optional: Step ids to retrieve the complete content (up to 5 at a time, only the first 5 will be returned for multi-pass, and the rest are listed in omitted_step_ids)","items":{"type":"integer"},"type":"array"},"task_id":{"description":"task id","type":"string"}},"required":["task_id","intent_id"],"type":"object"},"readOnly":true,"category":"gary-security"},{"name":"gary_get_worker_output","upstreamName":"get_worker_output","description":"Get the final output conclusion of this task or an intention (work) directly related to the task. The associated task results have source_task_id/inherited=true and are read-only. A normal end returns its summary; a stopped/abnormal work returns its last output up to the time of abort.","inputSchema":{"properties":{"intent_id":{"description":"Intent id (= work handle)","type":"integer"}},"required":["intent_id"],"type":"object"},"readOnly":true,"category":"gary-security"},{"name":"gary_get_worker_trace","upstreamName":"get_worker_trace","description":"View the [execution process] of a certain intention (work) (different from get_worker_output which only gives the final conclusion). Three usages:① Only pass intent_id → Return the summary stream of each step of the work (summary ≤ 100 words, including step_id; only the action outline, not including complete output);② intent_id + q → only returns the summary of steps that hit the keyword (search in both summary and complete output; still only gives summary, use ③ to see the content);③ intent_id + step_ids → Return the complete content (detail) of these steps; a maximum of 5 can be taken at a time. If the number exceeds 5, only the first 5 will be returned and the untaken ones will be notified in notice/omitted_step_ids.Typical process: First ①/② locate the step_id of the suspicious step, and then use ③ to obtain its complete output. There is no thinking step. Supports historical traces directly associated with tasks; the results have source_task_id/inherited=true and are read-only.","inputSchema":{"properties":{"intent_id":{"description":"Intent id (= work handle)","type":"integer"},"limit":{"description":"Return limit for summary streams/retrievals (optional)","type":"integer"},"q":{"description":"Keyword: only return summary/full output of steps that hit it (optional; mutually exclusive with step_ids)","type":"string"},"step_ids":{"description":"To get the step_id of the complete content (returned from ①/②; up to 5 are taken at a time, only the first 5 are returned for multi-pass, and the rest are listed in omitted_step_ids)","items":{"type":"integer"},"type":"array"}},"required":["intent_id"],"type":"object"},"readOnly":true,"category":"gary-security"},{"name":"gary_glob","upstreamName":"Glob","description":"Finds files whose path matches a glob pattern (supports ** for any depth, e.g. \"**/*.go\"). Returns paths sorted by modification time, newest first.\n\nUse this instead of `find`. The pattern matches paths relative to the search directory.","inputSchema":{"properties":{"path":{"description":"Directory to search (default working dir).","type":"string"},"pattern":{"description":"Glob pattern, e.g. src/**/*.go","type":"string"}},"required":["pattern"],"type":"object"},"readOnly":true,"category":"gary-security"},{"name":"gary_goal_met","upstreamName":"goal_met","description":"[End the entire mission immediately] - Only call it when you confirm that [all goals of the mission have been truly achieved and the overall conclusion] (note that the mission is [whole] completed; only achieving a certain goal/a flag/a vulnerability [does not count] - in that case, just mark the goal with prove_goal). ⚠️It is not used to \"end this round of planning\": if there are no new intentions to send in this round, or if you are waiting for worker output, just [end the round directly, do not adjust this tool] (0 intentions is completely normal). In normal judgment, priority is given to using prove_goal to prove the goals one by one; goal_met is just a means to bypass proving one by one and directly end from the overall situation.","inputSchema":{"properties":{"reason":{"description":"Evidence that the goal was actually achieved; ending a turn with no new direction is not goal completion.","type":"string"}},"required":["reason"],"type":"object"},"readOnly":false,"category":"gary-security"},{"name":"gary_graph_overview","upstreamName":"graph_overview","description":"(Exploration link diagram) Exploration situation distillation summary: asset count, interfaceless site, frontier, discovery, hints (strategic hints from human/master agent, must be included when generating intent). Adjust it first when planning.","inputSchema":{"properties":{},"type":"object"},"readOnly":true,"category":"gary-security"},{"name":"gary_grep","upstreamName":"Grep","description":"A powerful search tool built on ripgrep\n\nUsage:\n- ALWAYS use Grep for search tasks. NEVER invoke `grep` or `rg` as a Bash command. The Grep tool has been optimized for correct permissions and access.\n- Supports full regex syntax (e.g., \"log.*Error\", \"function\\s+\\w+\")\n- Filter files with glob parameter (e.g., \"*.js\", \"**/*.tsx\") or type parameter (e.g., \"js\", \"py\", \"rust\")\n- Output modes: \"content\" shows matching lines, \"files_with_matches\" shows only file paths (default), \"count\" shows match counts\n- Use Agent tool for open-ended searches requiring multiple rounds\n- Pattern syntax: Uses ripgrep (not grep) - literal braces need escaping (use `interface\\{\\}` to find `interface{}` in Go code)\n- Prefer `head_limit` to avoid large result sets.\n- Multiline matching: By default patterns match within single lines only. For cross-line patterns like `struct \\{[\\s\\S]*?field`, use `multiline: true`\n- Prefer Grep over terminal rg/grep for codebase search unless you specifically need shell features.","inputSchema":{"properties":{"-A":{"description":"Lines of context to show after each match (content mode).","type":"integer"},"-B":{"description":"Lines of context to show before each match (content mode).","type":"integer"},"-C":{"description":"Lines of context before and after each match (content mode).","type":"integer"},"-i":{"description":"Case-insensitive.","type":"boolean"},"-n":{"description":"Show line numbers (content mode). Default true.","type":"boolean"},"glob":{"description":"Only search files matching this glob, e.g. *.go or *.{ts,tsx}","type":"string"},"head_limit":{"description":"Limit output to the first N results (lines/files/counts). Default 250; pass 0 for unlimited.","type":"integer"},"multiline":{"description":"Multiline mode: . matches newlines and patterns may span lines. Default false.","type":"boolean"},"offset":{"description":"Skip the first N results before applying head_limit (paging). Default 0.","type":"integer"},"output_mode":{"description":"files_with_matches (default) | content | count","type":"string"},"path":{"description":"File or directory to search. Defaults to the working directory.","type":"string"},"pattern":{"description":"RE2 regular expression to search for.","type":"string"},"type":{"description":"Only search a file type, e.g. go, py, js, ts, rust, java. Unknown types are treated as an extension (type:foo → *.foo).","type":"string"}},"required":["pattern"],"type":"object"},"readOnly":true,"category":"gary-security"},{"name":"gary_insert_assets","upstreamName":"insert_assets","description":"Batch registration of newly discovered assets, multiple types can be mixed at one time (see enumeration for type).Required fields for each type: root_domain→domain; ip→ip (must be IPv4/IPv6, not host name); subdomain→domain; app→app_name; service(HTTP)→url; service (non-HTTP)→service_name+port (fill in at least one ip/domain); endpoint→url+method. The meaning of the remaining fields can be found in their respective descriptions.auth/technologies/params is appended and does not overwrite the original value.Returns: {results:[{index,id,type}], errors:[{index,error}]}","inputSchema":{"properties":{"assets":{"description":"Asset array, each element corresponds to an asset record","items":{"properties":{"app_icp":{"description":"Apply ICP filing (optional)","type":"string"},"app_name":{"description":"Application name (required for app type)","type":"string"},"auth":{"description":"A list of discovered authentication information, each containing fields such as type/username/password (optional, appending will not overwrite)","items":{"type":"object"},"type":"array"},"bound_domains":{"description":"List of domain names bound to this IP (ip type optional)","items":{"type":"string"},"type":"array"},"bundle_id":{"description":"Bundle ID (optional for app type)","type":"string"},"category":{"description":"Application classification (optional)","type":"string"},"company_id":{"description":"Attributing company id (optional for app type; app cannot be automatically attributed by scope and needs to be specified explicitly. id is returned by add_company_scope)","type":"integer"},"content_length":{"description":"HTTP response body bytes (optional)","type":"integer"},"description":{"description":"Application description (optional)","type":"string"},"domain":{"description":"Root domain name or subdomain name (root_domain/subdomain required)","type":"string"},"favicon_mmh3":{"description":"favicon MMH3 hash (optional)","type":"string"},"icp":{"description":"ICP registration number (optional)","type":"string"},"ip":{"description":"IP address must be an IPv4/IPv6 address, and the host name cannot be filled in (please use the domain field of type=subdomain for the host name); the ip type is required; the service/endpoint type can be filled in and is used to associate IP","type":"string"},"method":{"description":"HTTP method: GET/POST/PUT/PATCH/DELETE, etc. (endpoint is required)","type":"string"},"open_ports":{"description":"Open port list (ip type optional)","items":{"properties":{"port":{"description":"port number","type":"integer"},"service":{"description":"Service name, such as http/ssh/mysql, etc. (optional)","type":"string"}},"required":["port"],"type":"object"},"type":"array"},"page_title":{"description":"Page title (optional)","type":"string"},"params":{"description":"Request parameter list, each containing location(query/body/header/path)/name/value/type (optional, appending will not overwrite)","items":{"type":"object"},"type":"array"},"port":{"description":"Port number (required when service is not HTTP)","type":"integer"},"record_type":{"description":"DNS resolution type: A/AAAA/CNAME/MX, etc. (subdomain optional)","type":"string"},"record_value":{"description":"List of DNS resolution values (subdomain is optional, such as [\"1.2.3.4\",\"2.3.4.5\"])","items":{"type":"string"},"type":"array"},"service_name":{"description":"Service name, such as ssh/mysql/redis (required when service is not HTTP)","type":"string"},"status_code":{"description":"HTTP response status code, such as 200/301/403/404 (optional)","type":"integer"},"technologies":{"description":"Fingerprint/technology stack list, such as [\"Nginx\", \"Vue\", \"Bootstrap\"] (optional)","items":{"type":"string"},"type":"array"},"type":{"description":"Asset type","enum":["root_domain","ip","subdomain","app","service","endpoint"],"type":"string"},"url":{"description":"Full URL, including protocol and port (required for HTTP service; service_type is automatically set to http)","type":"string"}},"required":["type"],"type":"object"},"type":"array"}},"required":["assets"],"type":"object"},"readOnly":false,"category":"gary-security"},{"name":"gary_kill_work","upstreamName":"kill_work","description":"Terminate a running intent (work). Used to stop wandering/meaningless exploration; the terminated intention is marked as stopped and will no longer be automatically regained. Use get_worker_output first to see what it is doing before deciding.","inputSchema":{"properties":{"intent_id":{"description":"Intent id to terminate (= work handle)","type":"integer"}},"required":["intent_id"],"type":"object"},"readOnly":false,"category":"gary-security"},{"name":"gary_list_assets","upstreamName":"list_assets","description":"Query the asset library: DSL expression search, or direct fetching by id/ids; paging is supported. Only assets within the test range of [this task and directly related tasks] will be returned.DSL: field=value fuzzy (ILIKE) | field==value precise | field!=value exclusion | numeric field support > >= < <= | bare words = full text fuzzy; AND/OR combination (AND has high priority), grouping with parentheses can be used. Asset types use independent type parameters and are not written into the DSL.When id/ids are not passed, dsl must be non-empty (unconditional full query is not allowed).Available fields: domain (root/sub/service domain name), root_domain, ip, url, page_title, icp, service_name, app_name, method (such as GET/POST), service_type (http|other), record_type (such as A/CNAME), technology (array, = fuzzy == precise), port/status_code/company_id (integer).Example: status_code>=400 AND technology=shiro; (port==80 OR port==443) AND technology=nginx","inputSchema":{"properties":{"dsl":{"description":"DSL query expression (see tool description for syntax/fields). Must be non-empty if id/ids are not passed.","type":"string"},"id":{"description":"Get directly by individual asset id (optional, mutually exclusive with dsl/type)","type":"integer"},"ids":{"description":"Get directly by multiple asset IDs (optional, mutually exclusive with dsl/type)","items":{"type":"integer"},"type":"array"},"limit":{"description":"Result limit, default 10 (optional)","type":"integer"},"offset":{"description":"Paging offset, default 0 (optional)","type":"integer"},"type":{"description":"Asset type filtering: root_domain|ip|subdomain|app|service|endpoint (independent field, can be superimposed with dsl; type alone is not enough to query, dsl is still needed)","type":"string"}},"type":"object"},"readOnly":true,"category":"gary-security"},{"name":"gary_list_companies","upstreamName":"list_companies","description":"List the [enterprise/company] in the asset library, their asset scope and the number of vested assets. Used to see which companies,Get company_id (used when insert_assets is associated with app and list_assets is filtered by company_id).Optional search: fuzzy filter by company name (not case sensitive), leave blank to return all.","inputSchema":{"properties":{"search":{"description":"Fuzzy filter by company name (optional, case-insensitive); leave blank to return all","type":"string"}},"type":"object"},"readOnly":true,"category":"gary-security"},{"name":"gary_list_facts","upstreamName":"list_facts","description":"List the [Exploration Facts/Conclusions] of this task and directly related tasks in pages, with the latest first (compact: id+summary+status, the summary will be truncated if it is too long, use node_detail(id) for the full text). All parameters are optional: limit (default 20, upper limit 100), before (cursor, next_before returned by passing the previous page takes the older page; omit /0 = latest page), q (filter by summary keyword). Return {facts, total, has_more, next_before}: total is the filtered total, and when has_more=true, use next_before to continue page turning. Associated task entries have source_task_id/inherited=true and are read-only. See list_findings for vulnerabilities.","inputSchema":{"properties":{"before":{"description":"Paged cursor: only return older facts with id less than this value; omitted or 0 = latest page","type":"integer"},"limit":{"description":"Result count, default 20, maximum 100","type":"integer"},"q":{"description":"Filter by fact summary keyword (not case sensitive); omitted = no filtering","type":"string"}},"type":"object"},"readOnly":true,"category":"gary-security"},{"name":"gary_list_findings","upstreamName":"list_findings","description":"List [confirmed vulnerabilities] of this task and directly related tasks (compact: id+task_id+intent_id+vulnclass+severity+summary+status). Associated task entries have source_task_id/inherited=true and are read-only. Only vulnerabilities are included here; use list_facts for general facts and node_detail(id) for details.","inputSchema":{"properties":{},"type":"object"},"readOnly":true,"category":"gary-security"},{"name":"gary_list_goals","upstreamName":"list_goals","description":"List the target nodes of this task and their status (open/met) to determine whether they are achieved.","inputSchema":{"properties":{},"type":"object"},"readOnly":true,"category":"gary-security"},{"name":"gary_list_llm_profiles","upstreamName":"list_llm_profiles","description":"List available LLM profiles (profiles): id, name, model, format, whether it is the currently active profile. Use the id to specify the subtask-specific LLM for the llm_profile_id parameter of spawn_task (such as a cheap model for reconnaissance, a strong model for exploitation). Does not include API Key.","inputSchema":{"properties":{},"type":"object"},"readOnly":true,"category":"gary-security"},{"name":"gary_list_task_findings","upstreamName":"list_task_findings","description":"Read the confirmed vulnerability of the specified task (including flag/PoC; each strip has id/task_id/intent_id/vulnclass/severity/summary/status), and use task_id to specify the task.","inputSchema":{"properties":{"task_id":{"description":"task id","type":"string"}},"required":["task_id"],"type":"object"},"readOnly":true,"category":"gary-security"},{"name":"gary_list_task_worker_traces","upstreamName":"list_task_worker_traces","description":"List the work (intent) + the number of steps that have been run in the specified task, which can be used to find out which work is worth looking at (reuse get_task_worker_trace).","inputSchema":{"properties":{"task_id":{"description":"task id","type":"string"}},"required":["task_id"],"type":"object"},"readOnly":true,"category":"gary-security"},{"name":"gary_list_tasks","upstreamName":"list_tasks","description":"List all tasks (id/description/goal/status/running time/parent task/LLM configuration), and orchestrate the agent to use it to grasp the overall situation, see which tasks are stuck for too long, and which LLM should be used for each. Running time: running = created → now, final state = created → last activity (seconds). llm_profile: Configuration name used by task planner/worker, (activation configuration) = follow global activation.","inputSchema":{"properties":{},"type":"object"},"readOnly":true,"category":"gary-security"},{"name":"gary_list_untested_assets","upstreamName":"list_untested_assets","description":"Query the assets within the scope of [this task and directly related tasks] that have not been covered by fact anchors (the related range is read-only, for you to judge whether to make a supplementary test, and does not make decisions for you).Optional filtering by asset type: root_domain/subdomain/service/app/endpoint/ip.Pagination: page starts from 1, page_size defaults to 10. Return {assets:[{id,type,label}], total, page, page_size}. Only task context is available.","inputSchema":{"properties":{"page":{"description":"One-based page number, default 1","type":"integer"},"page_size":{"description":"Number per page (default 10)","type":"integer"},"type":{"description":"Asset type filtering (optional): root_domain/subdomain/service/app/endpoint/ip","type":"string"}},"type":"object"},"readOnly":true,"category":"gary-security"},{"name":"gary_ls","upstreamName":"LS","description":"Lists the files and subdirectories of a directory (non-recursive). Use Glob to match by pattern across depth, or Grep to search contents.\n\npath may be absolute or relative to the working directory; defaults to the working directory.","inputSchema":{"properties":{"path":{"description":"Directory to list (default working directory).","type":"string"}},"type":"object"},"readOnly":true,"category":"gary-security"},{"name":"gary_multiedit","upstreamName":"MultiEdit","description":"Applies several exact string replacements to a single file in one atomic operation. Edits are applied in order; if any old_string fails to match (or isn't unique without replace_all), the whole operation aborts and the file is left unchanged.\n\nUse this instead of multiple Edit calls on the same file. Each edit's old_string must match the file as modified by the preceding edits. Read the file first.","inputSchema":{"properties":{"edits":{"description":"Edits to apply in order.","items":{"properties":{"new_string":{"description":"Replacement text.","type":"string"},"old_string":{"description":"Exact text to replace.","type":"string"},"replace_all":{"description":"Replace all occurrences.","type":"boolean"}},"required":["old_string","new_string"],"type":"object"},"type":"array"},"file_path":{"description":"Path of the file to edit.","type":"string"}},"required":["file_path","edits"],"type":"object"},"readOnly":false,"category":"gary-security"},{"name":"gary_node_detail","upstreamName":"node_detail","description":"Get the complete content of the [Exploration Graph Node] of this task or the directly related task by id. Inherited nodes have source_task_id/inherited=true and are read-only. Only the exploration node id returned by list_facts/list_findings/graph_overview; for assets, please use list_assets/asset_neighbors.","inputSchema":{"properties":{"id":{"description":"Exploration graph node id (non-asset id)","type":"integer"}},"required":["id"],"type":"object"},"readOnly":true,"category":"gary-security"},{"name":"gary_pause_task","upstreamName":"pause_task","description":"Pauses the specified task (stops its planner/worker loop).","inputSchema":{"properties":{"task_id":{"description":"task id to pause","type":"string"}},"required":["task_id"],"type":"object"},"readOnly":false,"category":"gary-security"},{"name":"gary_prove_goal","upstreamName":"prove_goal","description":"Called when you judge that a discovery/fact proves that a certain goal has been achieved: connect the evidence node to the target node and mark the target met.","inputSchema":{"properties":{"evidence_id":{"description":"the discovery/fact node id that proves it","type":"integer"},"goal_id":{"description":"target node id","type":"integer"},"reason":{"description":"Why does this evidence meet this goal?","type":"string"}},"required":["goal_id","evidence_id"],"type":"object"},"readOnly":false,"category":"gary-security"},{"name":"gary_read","upstreamName":"Read","description":"Reads a file from the local filesystem and returns its contents with line numbers. Use offset/limit for large files. Always read a file before editing it.\n\nfile_path may be absolute or relative to the working directory. Output lines are prefixed with their 1-based line number.","inputSchema":{"properties":{"file_path":{"description":"Path to the file to read.","type":"string"},"limit":{"description":"Max lines to read (default 2000).","type":"integer"},"offset":{"description":"1-based line to start from.","type":"integer"}},"required":["file_path"],"type":"object"},"readOnly":true,"category":"gary-security"},{"name":"gary_record_fact","upstreamName":"record_fact","description":"Write the exploration [fact/conclusion] into the exploration graph and connect it to the intention (intent_id) that generated it. Used to record exploration results - including fingerprints/enumerations, etc. [positive conclusions], and 'port closed'/'parameters cannot be injected'/'no login entrance found' etc. [negative conclusions].⚠️Multiple observations from an exploration should be [summarized into one fact], do not split into multiple pieces. If they can be combined into one fact, try to express it with one fact: summary = a concluding sentence for this conclusion, detail = relevant details (can contain multiple specific items). Example: Fingerprint intent → a fact {summary:'Identified the technology stack and response characteristics of the An intention usually produces only one fact. If it is broken down too much, the graph will expand infinitely.★The facts array is used to write multiple [different from each other] conclusions at one time (the intent_id can be omitted for each one, and the top-level intent_id is used by default). Returns the ids array, in the same length and order as facts.⚠️Only write the conclusions you [actually see] in the tool output, don’t make up your mind. evidence and confidence are used to prevent inaccurate conclusions from contaminating the graph:· evidence = [one line] key evidence to support this conclusion (command + one or two lines of output that best proves it), **must be concise** - the details are already in detail, don't stick to a large section of output here.· confidence=observed (directly seen in the output) | inferred (inferred from the phenomenon).· **Negative conclusion** (cannot be injected/port closed/no entrance found, etc.) only write \"observation + exploratory reading\" - state what you actually saw, whether the direction is given up is determined by the planner comprehensively; be sure to mark evidence, if the means are not exhausted or the evidence is weak (including only exploring once, it looks like), mark it as inferred, mark it as observed if it is indeed exhausted and directly seen.","inputSchema":{"properties":{"asset_ids":{"description":"Related asset id (optional, 0/1/multiple): which assets are involved in this fact","items":{"type":"integer"},"type":"array"},"confidence":{"description":"observed (directly seen in the output) | inferred (inferred from the phenomenon). Negative conclusions must be labeled truthfully.","type":"string"},"detail":{"description":"Relevant details for this fact: Write multiple observations from this exploration here","type":"string"},"evidence":{"description":"[One line] Key evidence: command + the one or two lines of output that best prove the conclusion. Be concise and don’t stick to large sections of output (please leave details in detail).","type":"string"},"facts":{"description":"[Use when there are multiple different conclusions] Fact array, the element field is the same as the top-level field below (summary/detail/evidence/confidence/intent_id/asset_ids); if intent_id is omitted, the top-level intent_id is used. The returned ids are of the same length and order as this array.","items":{"type":"object"},"type":"array"},"intent_id":{"description":"The intent id that generated this fact (the intent you received; used as the default for each item in batches)","type":"integer"},"summary":{"description":"[Concluding sentence] for the conclusion of this exploration (a summary of detail)","type":"string"}},"type":"object"},"readOnly":false,"category":"gary-security"},{"name":"gary_record_finding_retest_result","upstreamName":"record_finding_retest_result","description":"Save the only conclusion for the current retest session; the original vulnerability evidence and report remain unchanged. When the session ends successfully and the conclusion is fixed, the system automatically changes the vulnerability status to fixed; other conclusions retain their original status. Evidence of this actual inspection must be provided, and if it cannot be confirmed, the cause of the obstruction must be stated.","inputSchema":{"properties":{"evidence":{"description":"Markdown: The actual steps, observations, comparisons, and conclusion basis of this time; if it cannot be confirmed, the checked content and blocking reasons are listed.","type":"string"},"summary":{"description":"Summary of the conclusions of this retest","type":"string"},"verdict":{"enum":["reproduced","fixed","inconclusive"],"type":"string"}},"required":["verdict","summary","evidence"],"type":"object"},"readOnly":false,"category":"gary-security"},{"name":"gary_report_finding","upstreamName":"report_finding","description":"Record confirmed vulnerabilities and use evidence to provide verifiable evidence such as command output and logs. The task context passes the current intent_id. The returned finding_id is the individual vulnerability record ID, and finding_node_id is the discovery node ID (the first row holds the node number).","inputSchema":{"properties":{"asset_ids":{"description":"Affected asset id","items":{"type":"integer"},"type":"array"},"evidence":{"description":"Evidence/PoC text","type":"string"},"evidence_hint_id":{"description":"Optional: The prompt node ID corresponding to this vulnerability in this task automatically carries its structured traffic_refs; inheritance prompts or prompts of other vulnerabilities cannot be referenced.","type":"integer"},"intent_id":{"description":"The intent id of the current task","type":"integer"},"name":{"description":"Vulnerability name","type":"string"},"severity":{"description":"critical|high|medium|low","type":"string"},"summary":{"description":"Discovery summary","type":"string"},"traffic_refs":{"description":"Optional; first search for HTTP/HTTPS vulnerabilities and verify that the request/response indeed supports the vulnerability conclusion one by one, and then fill in the real ID in the order of recurrence. Omit or pass [] when TCP and other non-HTTP vulnerabilities are not collected or the exact record cannot be found, and the report will not be blocked; the reason can be explained in evidence and other verifiable evidence can be provided. Do not guess IDs, infer associations by domain/time, or repeat probes only for patch packets. Purpose baseline normal control / proof vulnerability proof / verification supplementary verification / supporting auxiliary evidence.","items":{"properties":{"note":{"description":"How does this traffic support the vulnerability conclusion?","type":"string"},"role":{"enum":["baseline","proof","verification","supporting"],"type":"string"},"traffic_id":{"description":"The real traffic ID returned by traffic_search","type":"string"}},"required":["traffic_id"],"type":"object"},"type":"array"},"vulnclass":{"description":"Vulnerability Category","type":"string"}},"required":["vulnclass","severity","summary"],"type":"object"},"readOnly":false,"category":"gary-security"},{"name":"gary_search_all_worker_traces","upstreamName":"search_all_worker_traces","description":"[It is usually not recommended because most of the information has been given in the system] Search by keyword (q) in [Execution process of other work in this task] - used to retrieve things that a worker has seen but has not been written into fact (a certain path/token/error report, etc.).Your own steps for this intention (those already in your context) are automatically excluded.Only the summary of hit steps (summary≤100 words) is returned, each with intent_id; based on this, use get_worker_trace(intent_id, step_ids=[...]) to get the complete content.","inputSchema":{"properties":{"limit":{"description":"Result limit, default 100 (optional)","type":"integer"},"q":{"description":"Keywords (search in summary + complete output of all work steps)","type":"string"}},"required":["q"],"type":"object"},"readOnly":true,"category":"gary-security"},{"name":"gary_search_task_worker_traces","upstreamName":"search_task_worker_traces","description":"Search the execution process of all work in the specified task by keyword (return hit step summary + intent_id).","inputSchema":{"properties":{"q":{"description":"Search keywords","type":"string"},"task_id":{"description":"task id","type":"string"}},"required":["task_id","q"],"type":"object"},"readOnly":true,"category":"gary-security"},{"name":"gary_set_constraints","upstreamName":"set_constraints","description":"Add operation constraints to [this task] to frame the exploration boundary: type=allow (operations allowed) or deny (operations prohibited).Constraints = regulations on \"what operations can/cannot be done\" (such as \"only test the current port, do not scan other ports\", \"forbidden to write operations to the production library\", \"only allow passive reconnaissance\"), not the goal, nor the attack step.★Priority batch: Put multiple items into the constraints array and submit them at once, and return ids with the same length and order (failure item id=0, see errors for details). For a single item, constraints are omitted and given directly to the top-level text/type.Only register the [clearly written] constraints in the task goal/description, do not make them up; use deny (more conservative) when you are not sure about the type.","inputSchema":{"properties":{"constraints":{"description":"[Use this first] The constraint array to be added is processed in order. Each element: text (required, one constraint) + type (allow|deny). The returned ids are of the same length and order as this array.","items":{"type":"object"},"type":"array"},"text":{"description":"[Single item] The content of an operation constraint","type":"string"},"type":{"description":"[Single item] allow (allow) or deny (forbidden); default processing is deny","type":"string"}},"type":"object"},"readOnly":false,"category":"gary-security"},{"name":"gary_set_goals","upstreamName":"set_goals","description":"Add a new exploration goal to [this task]. Objective = final deliverable/verifiable outcome, not attack steps or reconnaissance actions.★Priority batch: Put multiple goals into the goals array and submit them once, and return ids with the same length and order (failure item id=0, see errors for details). For a single article, goals are omitted and given directly to the top-level text.vulnclass optional: corresponding to the vulnerability class (such as SQLi/IDOR), the business logic class target is left blank. Whether the goal is achieved or not is determined by the system and marked as met. This tool is only responsible for new additions.","inputSchema":{"properties":{"goals":{"description":"[Use this first] The target array to be added is processed in order. Each element: text (required, an independently verifiable end goal) + vulnclass (optional). The returned ids are of the same length and order as this array.","items":{"type":"object"},"type":"array"},"text":{"description":"[Single Article] An independently verifiable end goal","type":"string"},"vulnclass":{"description":"[Single entry] Corresponding vulnerability class (if clear), such as SQLi/IDOR; business logic target can be left blank","type":"string"}},"type":"object"},"readOnly":false,"category":"gary-security"},{"name":"gary_shell_close","upstreamName":"shell_close","description":"Close an interactive session, terminate its process and release its PTY.","inputSchema":{"properties":{"session_id":{"description":"Session ID","type":"string"}},"required":["session_id"],"type":"object"},"readOnly":false,"category":"gary-security"},{"name":"gary_shell_list","upstreamName":"shell_list","description":"List all current interactive sessions and their states.","inputSchema":{"properties":{},"type":"object"},"readOnly":true,"category":"gary-security"},{"name":"gary_shell_open","upstreamName":"shell_open","description":"Open a persistent PTY session for an interactive program or a program requiring a real terminal, such as msfconsole, ssh, mysql, a Python REPL, a password prompt or nc. Returns session_id. Use Bash for one-shot noninteractive commands. interactive waits for a prompt or silence and returns startup output; hands-free (default) returns immediately and can be polled with shell_read; dispatch returns immediately and notifies on completion; monitor watches keywords and sends notifications without ending the session. Sessions live only in the running container process. Set prompt_regex to recognize a precise completion prompt, such as 'msf6? >\\s*$'. Close unused sessions with shell_close.","inputSchema":{"properties":{"cols":{"description":"Optional PTY columns (default 80)","type":"integer"},"command":{"description":"Interactive program to start, such as 'msfconsole -q', 'ssh user@host' or 'python3'","type":"string"},"mode":{"description":"interactive | hands-free (default) | dispatch | monitor","type":"string"},"prompt_regex":{"description":"Optional completion prompt regular expression, matched at the end of output","type":"string"},"quiet_ms":{"description":"Optional milliseconds of silence indicating completion (default 8000)","type":"integer"},"rows":{"description":"Optional PTY rows (default 24)","type":"integer"},"startup_grace_ms":{"description":"Optional startup grace period in milliseconds, during which quiet detection is disabled (default 15000)","type":"integer"},"watch":{"description":"Required in monitor mode: keywords or regular expressions to watch; each matching pattern triggers one notification.","items":{"type":"string"},"type":"array"}},"required":["command"],"type":"object"},"readOnly":false,"category":"gary-security"},{"name":"gary_shell_read","upstreamName":"shell_read","description":"Read an interactive session without sending input. view=stream (default) returns incremental raw output; continue reading or set drain to retrieve all buffered output. view=screen returns a full terminal screen snapshot for programs such as vim or htop.","inputSchema":{"properties":{"drain":{"description":"stream: true returns all raw output since the last read, ignoring the limit","type":"boolean"},"max_bytes":{"description":"stream: maximum returned bytes (default 8192)","type":"integer"},"max_lines":{"description":"stream: maximum returned lines (default 200)","type":"integer"},"session_id":{"description":"Session ID","type":"string"},"since_cursor":{"description":"stream: read after this cursor; otherwise continue from the session cursor","type":"integer"},"view":{"description":"stream (default) | screen","type":"string"}},"required":["session_id"],"type":"object"},"readOnly":true,"category":"gary-security"},{"name":"gary_shell_send","upstreamName":"shell_send","description":"Send input to an interactive session. Combine text, submit, keys, hex and paste; inputs are sent in field order. wait=true (default) waits for command completion and returns incremental output.","inputSchema":{"properties":{"hex":{"description":"Hexadecimal raw bytes, such as ['0x1b','0x5b','0x41']","items":{"type":"string"},"type":"array"},"keys":{"description":"Named keys: ctrl+c/ctrl+d/tab/enter/esc/up/down/left/right/...","items":{"type":"string"},"type":"array"},"paste":{"description":"Multiline bracketed paste, without executing each line separately","type":"string"},"prompt_regex":{"description":"Optional override for the session completion prompt","type":"string"},"quiet_ms":{"description":"Optional quiet threshold in milliseconds (default 8000)","type":"integer"},"session_id":{"description":"Session ID returned by shell_open","type":"string"},"submit":{"description":"Append Enter after the supplied text","type":"boolean"},"text":{"description":"Input text, without automatically pressing Enter","type":"string"},"timeout_ms":{"description":"Optional hard wait timeout in milliseconds (default 120000)","type":"integer"},"wait":{"description":"Wait synchronously for command completion (default true)","type":"boolean"}},"required":["session_id"],"type":"object"},"readOnly":false,"category":"gary-security"},{"name":"gary_skill","upstreamName":"Skill","description":"Invokes a named skill — a reusable procedure — and returns its step-by-step instructions for you to follow. Use a skill when the task matches one of the available skills below.\n\nAvailable skills:\n- api-recon: Discover an authorized website’s API surface, routes and parameters through static harvest and safely mocked browser coverage.\n- playwright-cli: Automate browser interactions, inspect pages and run Playwright workflows.\n- scopesentry-mcp: Operate an authorized ScopeSentry instance through its configured MCP server.","inputSchema":{"properties":{"args":{"description":"Optional additional context for the skill.","type":"string"},"name":{"description":"The skill to invoke.","type":"string"}},"required":["name"],"type":"object"},"readOnly":true,"category":"gary-security"},{"name":"gary_sleep","upstreamName":"sleep","description":"Waits for N seconds, then returns. Use to let a backgrounded command make progress before reading its partial output with TaskOutput. Interrupted immediately if the run is paused or stopped.","inputSchema":{"properties":{"seconds":{"description":"Seconds to wait, 1-3600.","type":"integer"}},"required":["seconds"],"type":"object"},"readOnly":true,"category":"gary-security"},{"name":"gary_spawn_task","upstreamName":"spawn_task","description":"Create a new subtask and start the exploration engine, returning task_id. Used to assign one thing (such as a question/a goal) into an independent task. parent_ref Optional: Fill in the parent task id of the current orchestration association to make a parent-child association.","inputSchema":{"properties":{"description":{"description":"Task description (short title)","type":"string"},"goal":{"description":"Mission objectives (what to achieve)","type":"string"},"llm_profile_id":{"description":"Optional: Specify the LLM configuration id used by this subtask planner/worker (see list_llm_profiles); leave it blank to inherit the parent task and then roll back to the global activation configuration.","type":"integer"},"parent_ref":{"description":"Optional: Parent task id (for parent-child association)","type":"string"},"plan_heartbeat_seconds":{"description":"Optional: planner heartbeat trigger interval (seconds). This value is reached from the end of the last round of planning/the start of the task and there is no trigger during the period → trigger a round of planning (deadlock + wake up to supervise the flying worker). Leave blank or 0 = default 600(10min);","type":"integer"},"seed_first_intent":{"description":"Optional: It can be enabled for simple tasks. When creating, a seed intent (content = description + target) is directly sent to the worker to start running the test without waiting for the first round of planner; the default is false (follow the standard plan first and then execute).","type":"boolean"},"source_task_ids":{"description":"Optional: Read-only list of inherited source task ids (up to 8). Subtasks can have read-only references to the assets/conclusions these tasks have proven as starting points; this is content inheritance unlike parent_ref's pure parent-child pointer.","items":{"type":"string"},"type":"array"},"timeout_seconds":{"description":"Optional: Task-level timeout (seconds). After reaching the point, trigger the graceful ending and enter the timeout final state; leave it blank or 0 = no time limit","type":"integer"}},"required":["description","goal"],"type":"object"},"readOnly":false,"category":"gary-security"},{"name":"gary_steer_work","upstreamName":"steer_work","description":"Inject corrective instructions into a running intention (work) in real time without interrupting it or losing the progress made: the worker will receive your instructions and adjust accordingly before taking the next step. Used for [in-intention] corrections such as 'Don't go to X, focus on Y'; if the direction is completely wrong, you should use kill_work and then set a new intention. It is recommended to use get_worker_output first to see what it is doing.","inputSchema":{"properties":{"intent_id":{"description":"Intent id to correct (= work handle)","type":"integer"},"message":{"description":"Corrective instructions to the worker, clearly telling it what to stop and what to turn to","type":"string"}},"required":["intent_id","message"],"type":"object"},"readOnly":false,"category":"gary-security"},{"name":"gary_tasklist","upstreamName":"TaskList","description":"Lists the background tasks started in this session with their status, exit code, and command.","inputSchema":{"properties":{},"type":"object"},"readOnly":true,"category":"gary-security"},{"name":"gary_taskoutput","upstreamName":"TaskOutput","description":"Reads the output of a background task started by Bash (run_in_background) or Monitor. You can also Read the task's output-file path directly. Set block=true to wait for the task to finish first.\n\nProvide the task_id. With block=true the call waits until the task reaches a terminal state (up to timeout_ms) before returning its output.","inputSchema":{"properties":{"block":{"description":"Wait until the task finishes before returning (default false).","type":"boolean"},"max_bytes":{"description":"Max bytes of output to return from the tail (default 30000).","type":"integer"},"task_id":{"description":"The task id (e.g. task_1).","type":"string"},"timeout_ms":{"description":"Max wait when block=true (default 30000).","type":"integer"}},"required":["task_id"],"type":"object"},"readOnly":true,"category":"gary-security"},{"name":"gary_taskstop","upstreamName":"TaskStop","description":"Stops a running background task, killing its process tree. Pass a task_id, or omit it to stop all running tasks.\n\nProvide task_id to stop one task, or leave it empty to stop all running tasks.","inputSchema":{"properties":{"task_id":{"description":"The id of the task to stop. Empty stops all running tasks.","type":"string"}},"type":"object"},"readOnly":false,"category":"gary-security"},{"name":"gary_todowrite","upstreamName":"TodoWrite","description":"Records and updates a structured todo list for the current task. Use it to plan multi-step work and to mark progress — replace the whole list each call, marking exactly one item in_progress while working.\n\nstatus is one of: pending, in_progress, completed. Keep the list current: mark a task completed as soon as it's done; don't batch completions.","inputSchema":{"properties":{"todos":{"items":{"properties":{"content":{"type":"string"},"status":{"enum":["pending","in_progress","completed"],"type":"string"}},"required":["content","status"],"type":"object"},"type":"array"}},"required":["todos"],"type":"object"},"readOnly":false,"category":"gary-security"},{"name":"gary_traffic_blob","upstreamName":"traffic_blob","description":"Read the original text of very large request/response bodies in sections. The part shown as '...[truncated] @blob sha256:<hash>' in traffic_get is stored here. Pass the hash in to get the complete content. A maximum of 8KB can be returned at a time, and offset is used to continue reading (the total length will be given in the return result). Suitable for responses that exceed the inline threshold, such as browsing backup files, source code leaks, large JSON exports, etc.","inputSchema":{"properties":{"hash":{"description":"@blob sha256 in traffic_get: the following 64-bit hexadecimal value","type":"string"},"length":{"description":"Number of bytes read this time, default and maximum 8192","type":"integer"},"offset":{"description":"Starting byte offset, default 0","type":"integer"}},"required":["hash"],"type":"object"},"readOnly":true,"category":"gary-security"},{"name":"gary_traffic_get","upstreamName":"traffic_get","description":"Get the original request/response text of a captured traffic by id (it will be truncated if it is too large). Use it with traffic_search to avoid repeated curl.","inputSchema":{"properties":{"id":{"description":"id returned by traffic_search","type":"string"}},"required":["id"],"type":"object"},"readOnly":true,"category":"gary-security"},{"name":"gary_traffic_search","upstreamName":"traffic_search","description":"Query and record the target traffic captured by the proxy (host must be specified; supports bare host, host:port or complete URL, and can be filtered by URL substring or text keywords). When specifying a port, only the traffic of the service is returned to avoid packet stringing on different ports of the same IP. body_contains will perform a full-text search in the crawled request/response headers and body, supporting any substring and English (at least 3 characters). Only a very lightweight index (id/method/url/status/resp_len) is returned, without response content; after the result is not empty, traffic_get must be used to verify the request/response one by one, and then the ID that does support the current vulnerability is handed over to bind_finding_traffic. By default, only 3 items are returned, with a maximum of 10 items per page; use page to turn pages when there are many results.","inputSchema":{"properties":{"body_contains":{"description":"Full-text search of the body (optional, at least 3 characters), matching the header and body of the request/response, such as 'password' / 'root:x:0' / 'Intranet test'","type":"string"},"contains":{"description":"URL substring filtering (optional, such as 'api' / 'login')","type":"string"},"host":{"description":"Filter by host (required; e.g. '107.172.96.177', '107.172.96.177:8082' or 'http://107.172.96.177:8082/path')","type":"string"},"limit":{"description":"Number of items per page, default 3, maximum 10","type":"integer"},"page":{"description":"Zero-based page number, default 0, ordered by descending timestamp","type":"integer"}},"required":["host"],"type":"object"},"readOnly":true,"category":"gary-security"},{"name":"gary_update_custom_tool","upstreamName":"update_custom_tool","description":"Modify an existing custom tool (press key).","inputSchema":{"properties":{"agents":{"description":"Binding agent key (optional)","items":{"type":"string"},"type":"array"},"deferred":{"description":"Whether to delay (the shell type is invalid; only uncommon tools of command/script/http are enabled)","type":"boolean"},"description":{"description":"Description sent to the model","type":"string"},"enabled":{"description":"Whether to enable (default true)","type":"boolean"},"exec":{"description":"Execution specifications (not required for shell type): command→{command}; script→{code}; http→{method,url,headers,body,proxy,use_recording_proxy}","type":"object"},"key":{"description":"Custom tool key to be modified","type":"string"},"kind":{"description":"shell | command | script (Python only) | http. shell=bash environment statement (only informs the model that the tool can be called directly in bash without exec/schema); the other three require exec","type":"string"},"schema":{"description":"Parameter JSON-Schema (shell/command/script can be left blank; http is required and must contain properties)","type":"object"}},"required":["key","kind"],"type":"object"},"readOnly":false,"category":"gary-security"},{"name":"gary_update_finding_report","upstreamName":"update_finding_report","description":"Write/update [detailed report] for registered vulnerabilities (full text in Markdown, covering the entire paragraph with old content). finding_id passes the id returned by report_finding (the number in \"finding recorded: <id>\"). The report recommendations include: vulnerability overview, impact and harm, reproduction steps, evidence/PoC, and repair suggestions.","inputSchema":{"properties":{"evidence_version":{"description":"The evidence version returned by get_finding_traffic; used to prevent reports from overwriting new evidence changes","type":"integer"},"finding_id":{"description":"Target vulnerability id (id returned by report_finding)","type":"integer"},"report":{"description":"Full text of detailed report, Markdown format","type":"string"}},"required":["finding_id","report"],"type":"object"},"readOnly":false,"category":"gary-security"},{"name":"gary_update_mcp","upstreamName":"update_mcp","description":"Modify an existing MCP server (by id).","inputSchema":{"properties":{"args":{"description":"Command parameter array","items":{"type":"string"},"type":"array"},"command":{"description":"stdio startup command (such as npx)","type":"string"},"enabled":{"description":"Whether to enable (default true)","type":"boolean"},"env":{"description":"Environment variable {KEY:VALUE}","type":"object"},"id":{"description":"MCP server id to modify","type":"integer"},"insecure":{"description":"http: Skip TLS certificate verification (set to true when self-signing the certificate, default to false)","type":"boolean"},"name":{"description":"MCP server name","type":"string"},"transport":{"description":"stdio | http / sse","type":"string"},"url":{"description":"http/sse URL","type":"string"}},"required":["id","name","transport"],"type":"object"},"readOnly":false,"category":"gary-security"},{"name":"gary_update_skill_file","upstreamName":"update_skill_file","description":"Write/overwrite a file within a skill (default SKILL.md). Used to modify skill content or add scripts/references.","inputSchema":{"properties":{"content":{"description":"Complete content of the file","type":"string"},"file":{"description":"Relative path (optional, default SKILL.md, such as scripts/run.py)","type":"string"},"name":{"description":"skill name","type":"string"}},"required":["name","content"],"type":"object"},"readOnly":false,"category":"gary-security"},{"name":"gary_web_search","upstreamName":"web_search","description":"Search the web and return a ranked list of results (title, URL, description) — metadata only, up to 5 by default. Use WebFetch to read the full content of a specific URL. This makes an external network request.","inputSchema":{"properties":{"limit":{"description":"Maximum number of results to return (1-20). Default 5.","maximum":20,"minimum":1,"type":"integer"},"query":{"description":"The search query.","type":"string"}},"required":["query"],"type":"object"},"readOnly":true,"category":"gary-security"},{"name":"gary_webfetch","upstreamName":"WebFetch","description":"Fetches an HTTP(S) HTML page, documentation page, or API response and returns it as Markdown. Do not use this tool for static assets, including JavaScript, CSS, source maps, images, fonts, audio, or video—even if their URLs are found in a fetched page or explicitly requested. Fetch the owning page instead. Set `extract=true` to list comments, scripts, stylesheets, endpoints, forms, links, and meta tags. Listed asset URLs are for inspection only and must not be fetched. Large responses may be truncated. This makes an external network request.","inputSchema":{"properties":{"extract":{"description":"When true, append a RECON section preserving HTML comments, <script src>, inline-script endpoints, forms/inputs (including hidden), links and meta tags. Default false.","type":"boolean"},"url":{"description":"The absolute http(s) URL to fetch. JS/CSS/static-asset suffix URLs are not allowed.","type":"string"}},"required":["url"],"type":"object"},"readOnly":false,"category":"gary-security"},{"name":"gary_write","upstreamName":"Write","description":"Writes a file to the local filesystem, creating parent directories and overwriting any existing file. Prefer Edit for modifying existing files.\n\nProvide the complete file contents — Write replaces the whole file.","inputSchema":{"properties":{"content":{"description":"Full contents to write.","type":"string"},"file_path":{"description":"Path of the file to write.","type":"string"}},"required":["file_path","content"],"type":"object"},"readOnly":false,"category":"gary-security"}]};
